CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL CHECK (role IN ('admin','buyer')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_procurement_user() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','buyer')) $$;
REVOKE ALL ON FUNCTION public.is_procurement_user() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_procurement_user() TO authenticated;
CREATE TABLE public.supplier_memberships (user_id uuid NOT NULL, supplier_id text NOT NULL, PRIMARY KEY(user_id,supplier_id));
GRANT SELECT ON public.supplier_memberships TO authenticated;
GRANT ALL ON public.supplier_memberships TO service_role;
ALTER TABLE public.supplier_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_membership ON public.supplier_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_procurement_user());
CREATE TABLE public.supplier_portal_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id text NOT NULL, number text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'aguardando' CHECK(status IN ('aguardando','resposta','correcao','aprovado')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.supplier_portal_requests TO authenticated;
GRANT ALL ON public.supplier_portal_requests TO service_role;
ALTER TABLE public.supplier_portal_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_requests ON public.supplier_portal_requests FOR SELECT TO authenticated USING(public.is_procurement_user() OR EXISTS(SELECT 1 FROM public.supplier_memberships m WHERE m.user_id=auth.uid() AND m.supplier_id=supplier_portal_requests.supplier_id));
CREATE POLICY internal_insert_requests ON public.supplier_portal_requests FOR INSERT TO authenticated WITH CHECK(public.is_procurement_user());
CREATE POLICY internal_update_requests ON public.supplier_portal_requests FOR UPDATE TO authenticated USING(public.is_procurement_user()) WITH CHECK(public.is_procurement_user());
CREATE TABLE public.supplier_portal_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.supplier_portal_requests(id), user_id uuid NOT NULL, items jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.supplier_portal_responses TO authenticated;
GRANT ALL ON public.supplier_portal_responses TO service_role;
ALTER TABLE public.supplier_portal_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_responses ON public.supplier_portal_responses FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.supplier_portal_requests r WHERE r.id=request_id));